import json
import re
from typing import Dict, List, Tuple

SECTION_RE = re.compile(r"^\[(.+)]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.+)$")


def _split_sections(text: str) -> List[Tuple[str, List[str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        line = raw.rstrip("\n")
        if not line.strip():
            continue
        match = SECTION_RE.match(line.strip())
        if match:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = match.group(1).strip()
            current_lines = []
        else:
            if current_id is None:
                raise ValueError("Found content before any section header")
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    return sections


def _parse_choice_line(line: str) -> Tuple[str, str]:
    # Returns (choice_text, target)
    match = CHOICE_RE.match(line)
    if not match:
        raise ValueError(f"Invalid choice line: {line}")
    remainder = match.group(1).strip()
    if "->" in remainder:
        left, target = remainder.rsplit("->", 1)
        return left.strip(), target.strip()
    return remainder, ""


def _parse_line_block(lines: List[str]) -> Tuple[str, str, str]:
    # Returns (speaker, text, target)
    if not lines:
        return "", "", ""

    target = ""
    text_lines: List[str] = []

    for raw in lines:
        line = raw.strip()
        if "->" in line:
            left, tgt = line.rsplit("->", 1)
            line = left.strip()
            if not target:
                target = tgt.strip()
        text_lines.append(line)

    speaker = ""
    if text_lines:
        first = text_lines[0]
        if ":" in first:
            spk, rest = first.split(":", 1)
            speaker = spk.strip()
            text_lines[0] = rest.strip()

    text = "\n".join([t for t in text_lines if t])
    return speaker, text, target


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections = _split_sections(text)
    if not sections:
        raise ValueError("No sections found")

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    node_ids = set()

    for section_id, lines in sections:
        if section_id in node_ids:
            raise ValueError(f"Duplicate section id: {section_id}")
        node_ids.add(section_id)

        has_choices = any(CHOICE_RE.match(l.strip()) for l in lines)
        if has_choices:
            nodes.append({
                "id": section_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            })
            for line in lines:
                if not CHOICE_RE.match(line.strip()):
                    continue
                choice_text, target = _parse_choice_line(line)
                edges.append({
                    "from": section_id,
                    "to": target,
                    "text": choice_text,
                })
        else:
            speaker, text, target = _parse_line_block(lines)
            nodes.append({
                "id": section_id,
                "text": text,
                "speaker": speaker,
                "type": "line",
            })
            if target:
                edges.append({
                    "from": section_id,
                    "to": target,
                    "text": "",
                })

    # Auto-create End node if referenced
    targets = {e["to"] for e in edges if e["to"]}
    if "End" in targets and "End" not in node_ids:
        nodes.append({
            "id": "End",
            "text": "",
            "speaker": "",
            "type": "line",
        })
        node_ids.add("End")

    # Validate edge targets
    missing = sorted(t for t in targets if t not in node_ids)
    if missing:
        raise ValueError(f"Missing target nodes: {', '.join(missing)}")

    # Validate reachability
    start_id = sections[0][0]
    adjacency: Dict[str, List[str]] = {}
    for edge in edges:
        adjacency.setdefault(edge["from"], []).append(edge["to"])

    reachable = set()
    stack = [start_id]
    while stack:
        node = stack.pop()
        if node in reachable:
            continue
        reachable.add(node)
        for nxt in adjacency.get(node, []):
            if nxt:
                stack.append(nxt)

    unreachable = sorted(n for n in node_ids if n not in reachable)
    if unreachable:
        raise ValueError(f"Unreachable nodes: {', '.join(unreachable)}")

    return {"nodes": nodes, "edges": edges}


def _escape_dot(text: str) -> str:
    return (
        text.replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
    )


def _to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    nodes = graph["nodes"]
    edges = graph["edges"]

    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [shape=box];"]

    for node in nodes:
        node_id = node["id"]
        label_parts = [node_id]
        if node["type"] == "choice":
            label_parts.append("(choice)")
        else:
            if node.get("speaker"):
                label_parts.append(f"{node['speaker']}: {node.get('text', '')}")
            else:
                label_parts.append(node.get("text", ""))
        label = _escape_dot("\n".join([p for p in label_parts if p]))
        shape = "diamond" if node["type"] == "choice" else "box"
        lines.append(f"  \"{_escape_dot(node_id)}\" [label=\"{label}\", shape={shape}];")

    for edge in edges:
        frm = _escape_dot(edge["from"])
        to = _escape_dot(edge["to"])
        label = edge.get("text", "")
        if label:
            lines.append(f"  \"{frm}\" -> \"{to}\" [label=\"{_escape_dot(label)}\"];")
        else:
            lines.append(f"  \"{frm}\" -> \"{to}\";")

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
        f.write("\n")

    dot = _to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)
        f.write("\n")


if __name__ == "__main__":
    main()
